import { BarChart3 } from 'lucide-react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

const COLORS = ['#666CFF', '#8B8FFF', '#A8AAFF', '#C7C8FF', '#E0E1FF', '#B0B0B0'];

export default function CategoryPieChart({ data }) {
  if (!data || data.length === 0) return null;

  return (
    <div className="bg-white shadow-card rounded-xl p-5 h-full">
      <div className="flex items-center gap-2 mb-4">
        <BarChart3 size={20} className="text-primary" />
        <h2 className="text-base font-semibold text-text-primary">Répartition par Catégorie</h2>
      </div>
      <ResponsiveContainer width="100%" height={220}>
        <PieChart>
          <Pie data={data} dataKey="percentage" nameKey="name" innerRadius={50} outerRadius={90} paddingAngle={3}>
            {data.map((_, i) => (
              <Cell key={i} fill={COLORS[i % COLORS.length]} />
            ))}
          </Pie>
          <Tooltip formatter={(v) => `${v}%`} contentStyle={{ borderRadius: 10, border: 'none', boxShadow: '0 2px 10px rgba(76,78,100,0.1)' }} />
        </PieChart>
      </ResponsiveContainer>
      <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2">
        {data.map((c, i) => (
          <div key={c.name} className="flex items-center gap-1.5">
            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
            <span className="text-[11px] text-text-secondary">{c.name}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
