import { TrendingUp, TrendingDown } from 'lucide-react';

const ICONS = {
  totalRevenue: TrendingUp,
  avgOrderValue: TrendingUp,
  totalOrders: TrendingUp,
  totalProducts: TrendingUp,
  avgProductPrice: TrendingUp,
  topCategoryRevenue: TrendingUp,
  deliveryRate: TrendingUp,
  cancellationRate: TrendingDown,
};

const DECIMALS = {
  totalRevenue: 0,
  avgOrderValue: 2,
  totalOrders: 0,
  totalProducts: 0,
  avgProductPrice: 2,
  topCategoryRevenue: 0,
  deliveryRate: 1,
  cancellationRate: 1,
};

const SUFFIX = {
  totalRevenue: ' MAD',
  avgOrderValue: ' MAD',
  totalOrders: '',
  totalProducts: '',
  avgProductPrice: ' MAD',
  topCategoryRevenue: ' MAD',
  deliveryRate: '%',
  cancellationRate: '%',
};

export default function StatsCards({ stats }) {
  if (!stats) return null;
  const entries = Object.entries(stats).filter(([k]) => k !== 'period');
  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      {entries.map(([key, val]) => {
        const Icon = ICONS[key] || TrendingUp;
        const isDown = key === 'cancellationRate';
        const growth = val.growth ?? 0;
        const isPositive = isDown ? growth <= 0 : growth >= 0;
        return (
          <div key={key} className="bg-white shadow-card rounded-xl p-4 animate-fade-in">
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-medium text-text-secondary capitalize">
                {key.replace(/([A-Z])/g, ' $1').replace(/^./, (s) => s.toUpperCase())}
              </span>
              <Icon size={16} className={isPositive ? 'text-emerald-500' : 'text-red-400'} />
            </div>
            <p className="text-xl font-bold font-mono text-text-primary">
              {typeof val.value === 'number' ? val.value.toLocaleString('fr-FR', { minimumFractionDigits: DECIMALS[key], maximumFractionDigits: DECIMALS[key] }) : val.value}
              {SUFFIX[key]}
            </p>
            <div className={`flex items-center gap-1 mt-1.5 text-xs font-semibold ${isPositive ? 'text-emerald-600' : 'text-red-500'}`}>
              {isPositive ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
              <span>{isPositive ? '+' : ''}{growth}% vs mois dernier</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}
